Lemma mb_len_bound : forall es insz M, mb_ok es insz -> mb_cap es < 2 ^ M -> 9 <= M -> Z.of_nat (length es) + 8 <= M.
Proof.
  intros es insz M (K1 & K2 & F & G) CAP HM.
  destruct (mb_cap_geom es F G) as [C1 _].
  destruct es as [| e es']; [cbn; lia|].
  pose proof (C1 ltac:(discriminate)) as C. 
  destruct (Z_lt_le_dec (Z.of_nat (length (e :: es')) + 8) (M + 1)) as [LT|GE]; [lia|].
  exfalso. assert (2 ^ M <= 2 ^ (Z.of_nat (length (e :: es')) + 8)) by (apply Z.pow_le_mono_r; lia). lia.
Qed.
