  hs_RHEAP H s LB mh ->
  FieldsC mf (P + 80) (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) ->
  MBuf mh (P + 168) es insz -> MBuf m' (P + 168) (mb_put_es es insz n x) (insz + n) ->
